/* ==========================================================================
   Base de datos: panaderia_db  (convertida de MariaDB 10.4 / phpMyAdmin a SQL Server)
   Compatible con SQL Server 2016 o superior.
   Ejecutar completo (en SSMS: F5, o mejor con sqlcmd):
       sqlcmd -S localhost -E -i panaderia_db_sqlserver.sql
   Notas de la conversión:
     - AUTO_INCREMENT      -> IDENTITY(1,1)  (los IDs originales se conservan)
     - tinyint(1)          -> BIT
     - varchar / text      -> NVARCHAR / NVARCHAR(MAX) (acentos y ñ)
     - datetime/timestamp  -> DATETIME2(0); current_timestamp() -> SYSDATETIME()
     - enum(...)           -> NVARCHAR + restricción CHECK
     - procedimientos MySQL reescritos en T-SQL
   ========================================================================== */
SET NOCOUNT ON;
GO
IF DB_ID(N'panaderia_db') IS NULL
    CREATE DATABASE [panaderia_db];
GO
USE [panaderia_db];
GO

-- Limpieza previa (permite volver a ejecutar el script)
IF OBJECT_ID(N'dbo.sp_seed_compras', N'P') IS NOT NULL DROP PROCEDURE dbo.sp_seed_compras;
IF OBJECT_ID(N'dbo.sp_seed_produccion', N'P') IS NOT NULL DROP PROCEDURE dbo.sp_seed_produccion;
IF OBJECT_ID(N'dbo.sp_seed_ventas', N'P') IS NOT NULL DROP PROCEDURE dbo.sp_seed_ventas;
DECLARE @sql NVARCHAR(MAX) = N'';
SELECT @sql += N'ALTER TABLE ' + QUOTENAME(OBJECT_SCHEMA_NAME(parent_object_id)) + N'.' + QUOTENAME(OBJECT_NAME(parent_object_id))
             + N' DROP CONSTRAINT ' + QUOTENAME(name) + N';' + CHAR(10)
FROM sys.foreign_keys;
EXEC sp_executesql @sql;
IF OBJECT_ID(N'dbo.caja', N'U') IS NOT NULL DROP TABLE dbo.[caja];
IF OBJECT_ID(N'dbo.categorias', N'U') IS NOT NULL DROP TABLE dbo.[categorias];
