IF OBJECT_ID(N'dbo.detalle_receta', N'U') IS NOT NULL DROP TABLE dbo.[detalle_receta];
IF OBJECT_ID(N'dbo.empresa', N'U') IS NOT NULL DROP TABLE dbo.[empresa];
IF OBJECT_ID(N'dbo.items_compra', N'U') IS NOT NULL DROP TABLE dbo.[items_compra];
IF OBJECT_ID(N'dbo.items_produccion', N'U') IS NOT NULL DROP TABLE dbo.[items_produccion];
IF OBJECT_ID(N'dbo.items_venta', N'U') IS NOT NULL DROP TABLE dbo.[items_venta];
IF OBJECT_ID(N'dbo.marcas', N'U') IS NOT NULL DROP TABLE dbo.[marcas];
IF OBJECT_ID(N'dbo.metodos_pago', N'U') IS NOT NULL DROP TABLE dbo.[metodos_pago];
IF OBJECT_ID(N'dbo.movimientos_caja', N'U') IS NOT NULL DROP TABLE dbo.[movimientos_caja];
IF OBJECT_ID(N'dbo.movimientos_inventario', N'U') IS NOT NULL DROP TABLE dbo.[movimientos_inventario];
IF OBJECT_ID(N'dbo.permisos', N'U') IS NOT NULL DROP TABLE dbo.[permisos];
IF OBJECT_ID(N'dbo.producciones', N'U') IS NOT NULL DROP TABLE dbo.[producciones];
IF OBJECT_ID(N'dbo.productos', N'U') IS NOT NULL DROP TABLE dbo.[productos];
IF OBJECT_ID(N'dbo.proveedores', N'U') IS NOT NULL DROP TABLE dbo.[proveedores];
IF OBJECT_ID(N'dbo.recetas', N'U') IS NOT NULL DROP TABLE dbo.[recetas];
IF OBJECT_ID(N'dbo.registros_auditoria', N'U') IS NOT NULL DROP TABLE dbo.[registros_auditoria];
IF OBJECT_ID(N'dbo.roles', N'U') IS NOT NULL DROP TABLE dbo.[roles];
IF OBJECT_ID(N'dbo.roles_permisos', N'U') IS NOT NULL DROP TABLE dbo.[roles_permisos];
IF OBJECT_ID(N'dbo.sesiones_caja', N'U') IS NOT NULL DROP TABLE dbo.[sesiones_caja];
IF OBJECT_ID(N'dbo.unidades', N'U') IS NOT NULL DROP TABLE dbo.[unidades];
IF OBJECT_ID(N'dbo.usuarios', N'U') IS NOT NULL DROP TABLE dbo.[usuarios];
IF OBJECT_ID(N'dbo.variantes_producto', N'U') IS NOT NULL DROP TABLE dbo.[variantes_producto];
IF OBJECT_ID(N'dbo.ventas', N'U') IS NOT NULL DROP TABLE dbo.[ventas];
GO

-- ===================================================== TABLAS
CREATE TABLE dbo.[caja] (
    [id_caja] INT IDENTITY(1,1) NOT NULL,
    [id_usuario] INT NULL,
    [fecha_apertura] DATETIME2(0) NULL,
    [fecha_cierre] DATETIME2(0) NULL,
    [monto_inicio] DECIMAL(10,2) NULL,
    [monto_final] DECIMAL(10,2) NULL,
    [estado] NVARCHAR(20) NULL,
    CONSTRAINT [pk_caja] PRIMARY KEY ([id_caja])
);
CREATE TABLE dbo.[categorias] (
    [id] INT IDENTITY(1,1) NOT NULL,
    [nombre] NVARCHAR(150) NOT NULL,
    [descripcion] NVARCHAR(MAX) NULL,
    [creado_en] DATETIME2(0) NOT NULL CONSTRAINT [df_categorias_creado_en] DEFAULT (SYSDATETIME()),
    CONSTRAINT [pk_categorias] PRIMARY KEY ([id])
);
CREATE TABLE dbo.[clientes] (
    [id] INT IDENTITY(1,1) NOT NULL,
    [nombre] NVARCHAR(255) NOT NULL,
    [documento] NVARCHAR(50) NULL,
    [telefono] NVARCHAR(50) NULL,
    [email] NVARCHAR(150) NULL,
    [direccion] NVARCHAR(MAX) NULL,
    [creado_en] DATETIME2(0) NOT NULL CONSTRAINT [df_clientes_creado_en] DEFAULT (SYSDATETIME()),
    [activo] BIT NULL CONSTRAINT [df_clientes_activo] DEFAULT (1),
    CONSTRAINT [pk_clientes] PRIMARY KEY ([id])
);
CREATE TABLE dbo.[compras] (
    [id] INT IDENTITY(1,1) NOT NULL,
    [proveedor_id] INT NOT NULL,
    [numero_comprobante] NVARCHAR(100) NULL,
    [fecha] DATETIME2(0) NULL CONSTRAINT [df_compras_fecha] DEFAULT (SYSDATETIME()),
    [total] DECIMAL(12,2) NULL CONSTRAINT [df_compras_total] DEFAULT (0.00),
    [estado] NVARCHAR(50) NULL CONSTRAINT [df_compras_estado] DEFAULT (N'pendiente'),
    [observaciones] NVARCHAR(MAX) NULL,
    [creado_por] INT NULL,
    CONSTRAINT [pk_compras] PRIMARY KEY ([id])
);
CREATE TABLE dbo.[consumo_insumos] (
    [id] INT IDENTITY(1,1) NOT NULL,
    [produccion_id] INT NOT NULL,
    [variante_id] INT NOT NULL,
    [cantidad] DECIMAL(12,3) NOT NULL,
    [fecha] DATETIME2(0) NULL CONSTRAINT [df_consumo_insumos_fecha] DEFAULT (SYSDATETIME()),
    CONSTRAINT [pk_consumo_insumos] PRIMARY KEY ([id])
);
CREATE TABLE dbo.[detalle_receta] (
    [id] INT IDENTITY(1,1) NOT NULL,
    [receta_id] INT NOT NULL,
    [variante_id] INT NOT NULL,
    [cantidad] DECIMAL(12,3) NOT NULL,
    [observacion] NVARCHAR(255) NULL,
    CONSTRAINT [pk_detalle_receta] PRIMARY KEY ([id])
);
CREATE TABLE dbo.[empresa] (
    [id] INT IDENTITY(1,1) NOT NULL,
    [razon_social] NVARCHAR(255) NULL,
    [nombre_comercial] NVARCHAR(255) NULL,
    [ruc] NVARCHAR(20) NULL,
    [direccion] NVARCHAR(MAX) NULL,
    [telefono] NVARCHAR(50) NULL,
    [email] NVARCHAR(150) NULL,
    [logo] NVARCHAR(255) NULL,
    CONSTRAINT [pk_empresa] PRIMARY KEY ([id])
);
CREATE TABLE dbo.[items_compra] (
    [id] INT IDENTITY(1,1) NOT NULL,
    [compra_id] INT NOT NULL,
    [variante_id] INT NOT NULL,
    [cantidad] DECIMAL(12,3) NULL CONSTRAINT [df_items_compra_cantidad] DEFAULT (0.000),
    [costo_unitario] DECIMAL(12,2) NULL CONSTRAINT [df_items_compra_costo_unitario] DEFAULT (0.00),
    [margen_porcentaje] DECIMAL(6,2) NULL,
    [precio_venta_resultante] DECIMAL(12,2) NULL,
    [total] DECIMAL(12,2) NULL CONSTRAINT [df_items_compra_total] DEFAULT (0.00),
    CONSTRAINT [pk_items_compra] PRIMARY KEY ([id])
);
CREATE TABLE dbo.[items_produccion] (
    [id] INT IDENTITY(1,1) NOT NULL,
    [produccion_id] INT NOT NULL,
    [producto_id] INT NOT NULL,
    [cantidad] DECIMAL(12,3) NULL CONSTRAINT [df_items_produccion_cantidad] DEFAULT (0.000),
    CONSTRAINT [pk_items_produccion] PRIMARY KEY ([id])
);
CREATE TABLE dbo.[items_venta] (
    [id] INT IDENTITY(1,1) NOT NULL,
    [venta_id] INT NOT NULL,
    [variante_id] INT NOT NULL,
    [cantidad] DECIMAL(12,3) NULL CONSTRAINT [df_items_venta_cantidad] DEFAULT (0.000),
    [precio_unitario] DECIMAL(12,2) NULL CONSTRAINT [df_items_venta_precio_unitario] DEFAULT (0.00),
    [descuento] DECIMAL(12,2) NULL CONSTRAINT [df_items_venta_descuento] DEFAULT (0.00),
    CONSTRAINT [pk_items_venta] PRIMARY KEY ([id])
);
CREATE TABLE dbo.[marcas] (
    [id] INT IDENTITY(1,1) NOT NULL,
    [nombre] NVARCHAR(150) NOT NULL,
    [creado_en] DATETIME2(0) NOT NULL CONSTRAINT [df_marcas_creado_en] DEFAULT (SYSDATETIME()),
    CONSTRAINT [pk_marcas] PRIMARY KEY ([id])
);
CREATE TABLE dbo.[metodos_pago] (
    [id] INT IDENTITY(1,1) NOT NULL,
    [nombre] NVARCHAR(100) NOT NULL,
    [activo] BIT NULL CONSTRAINT [df_metodos_pago_activo] DEFAULT (1),
    CONSTRAINT [pk_metodos_pago] PRIMARY KEY ([id])
);
CREATE TABLE dbo.[movimientos_caja] (
    [id] INT IDENTITY(1,1) NOT NULL,
    [sesion_caja_id] INT NOT NULL,
    [tipo] NVARCHAR(20) NOT NULL,
    [monto] DECIMAL(12,2) NULL CONSTRAINT [df_movimientos_caja_monto] DEFAULT (0.00),
    [concepto] NVARCHAR(255) NULL,
    [fecha] DATETIME2(0) NULL CONSTRAINT [df_movimientos_caja_fecha] DEFAULT (SYSDATETIME()),
    CONSTRAINT [pk_movimientos_caja] PRIMARY KEY ([id])
);
CREATE TABLE dbo.[movimientos_inventario] (
    [variante_id] INT NOT NULL,
    [id] INT IDENTITY(1,1) NOT NULL,
    [tipo] NVARCHAR(50) NOT NULL,
    [motivo] NVARCHAR(255) NULL,
    [cantidad] DECIMAL(12,3) NULL CONSTRAINT [df_movimientos_inventario_cantidad] DEFAULT (0.000),
    [stock_anterior] DECIMAL(12,3) NULL CONSTRAINT [df_movimientos_inventario_stock_anterior] DEFAULT (0.000),
    [stock_nuevo] DECIMAL(12,3) NULL CONSTRAINT [df_movimientos_inventario_stock_nuevo] DEFAULT (0.000),
    [referencia_id] INT NULL,
    [fecha] DATETIME2(0) NULL CONSTRAINT [df_movimientos_inventario_fecha] DEFAULT (SYSDATETIME()),
    [usuario_id] INT NULL,
    CONSTRAINT [pk_movimientos_inventario] PRIMARY KEY ([id])
);
CREATE TABLE dbo.[permisos] (
    [id] INT IDENTITY(1,1) NOT NULL,
    [nombre] NVARCHAR(100) NOT NULL,
    [descripcion] NVARCHAR(MAX) NULL,
    CONSTRAINT [pk_permisos] PRIMARY KEY ([id])
);
CREATE TABLE dbo.[producciones] (
    [id] INT IDENTITY(1,1) NOT NULL,
    [referencia] NVARCHAR(100) NULL,
    [receta_id] INT NULL,
    [variante_salida_id] INT NULL,
    [cantidad_programada] DECIMAL(12,3) NULL CONSTRAINT [df_producciones_cantidad_programada] DEFAULT (0.000),
    [cantidad_obtenida] DECIMAL(12,3) NULL CONSTRAINT [df_producciones_cantidad_obtenida] DEFAULT (0.000),
    [merma_cantidad] DECIMAL(12,3) NOT NULL CONSTRAINT [df_producciones_merma_cantidad] DEFAULT (0.000),
    [merma_motivo] NVARCHAR(255) NULL,
    [fecha] DATETIME2(0) NULL CONSTRAINT [df_producciones_fecha] DEFAULT (SYSDATETIME()),
    [producido_por] INT NULL,
    [estado] NVARCHAR(50) NULL CONSTRAINT [df_producciones_estado] DEFAULT (N'pendiente'),
    [observaciones] NVARCHAR(MAX) NULL,
    CONSTRAINT [pk_producciones] PRIMARY KEY ([id])
);
CREATE TABLE dbo.[productos] (
    [id] INT IDENTITY(1,1) NOT NULL,
    [sku] NVARCHAR(100) NULL,
    [codigo_barras] NVARCHAR(100) NULL,
    [nombre] NVARCHAR(255) NOT NULL,
    [descripcion] NVARCHAR(MAX) NULL,
    [tipo] NVARCHAR(9) NOT NULL CONSTRAINT [df_productos_tipo] DEFAULT (N'insumo'),
    [controla_stock] BIT NOT NULL CONSTRAINT [df_productos_controla_stock] DEFAULT (1),
    [categoria_id] INT NULL,
    [unidad_id] INT NULL,
    [activo] BIT NULL CONSTRAINT [df_productos_activo] DEFAULT (1),
    [creado_en] DATETIME2(0) NOT NULL CONSTRAINT [df_productos_creado_en] DEFAULT (SYSDATETIME()),
    CONSTRAINT [pk_productos] PRIMARY KEY ([id]),
    CONSTRAINT [ck_productos_tipo] CHECK ([tipo] IN (N'insumo', N'elaborado', N'reventa'))
);
CREATE TABLE dbo.[proveedores] (
    [id] INT IDENTITY(1,1) NOT NULL,
    [nombre] NVARCHAR(255) NOT NULL,
    [documento] NVARCHAR(50) NULL,
    [contacto] NVARCHAR(150) NULL,
    [telefono] NVARCHAR(50) NULL,
    [email] NVARCHAR(150) NULL,
    [direccion] NVARCHAR(MAX) NULL,
    [creado_en] DATETIME2(0) NOT NULL CONSTRAINT [df_proveedores_creado_en] DEFAULT (SYSDATETIME()),
    [activo] BIT NULL CONSTRAINT [df_proveedores_activo] DEFAULT (1),
    CONSTRAINT [pk_proveedores] PRIMARY KEY ([id])
);
CREATE TABLE dbo.[recetas] (
    [id] INT IDENTITY(1,1) NOT NULL,
    [producto_id] INT NOT NULL,
    [nombre] NVARCHAR(200) NOT NULL,
    [descripcion] NVARCHAR(MAX) NULL,
    [rendimiento] DECIMAL(12,3) NULL CONSTRAINT [df_recetas_rendimiento] DEFAULT (1.000),
    [activo] BIT NULL CONSTRAINT [df_recetas_activo] DEFAULT (1),
    [creado_en] DATETIME2(0) NOT NULL CONSTRAINT [df_recetas_creado_en] DEFAULT (SYSDATETIME()),
    CONSTRAINT [pk_recetas] PRIMARY KEY ([id])
);
CREATE TABLE dbo.[registros_auditoria] (
    [id] INT IDENTITY(1,1) NOT NULL,
    [usuario_id] INT NULL,
    [accion] NVARCHAR(100) NOT NULL,
    [nombre_tabla] NVARCHAR(100) NULL,
    [id_registro] INT NULL,
    [datos_anteriores] NVARCHAR(MAX) NULL,
    [datos_nuevos] NVARCHAR(MAX) NULL,
    [creado_en] DATETIME2(0) NOT NULL CONSTRAINT [df_registros_auditoria_creado_en] DEFAULT (SYSDATETIME()),
    CONSTRAINT [pk_registros_auditoria] PRIMARY KEY ([id])
);
CREATE TABLE dbo.[roles] (
    [id_rol] INT IDENTITY(1,1) NOT NULL,
    [nombre] NVARCHAR(50) NOT NULL,
    [descripcion] NVARCHAR(MAX) NULL,
    [creado_en] DATETIME2(0) NOT NULL CONSTRAINT [df_roles_creado_en] DEFAULT (SYSDATETIME()),
    CONSTRAINT [pk_roles] PRIMARY KEY ([id_rol])
);
CREATE TABLE dbo.[roles_permisos] (
    [rol_id] INT NOT NULL,
    [permiso_id] INT NOT NULL,
    CONSTRAINT [pk_roles_permisos] PRIMARY KEY ([rol_id], [permiso_id])
);
CREATE TABLE dbo.[sesiones_caja] (
    [id] INT IDENTITY(1,1) NOT NULL,
    [usuario_id] INT NOT NULL,
    [abierto_en] DATETIME2(0) NULL CONSTRAINT [df_sesiones_caja_abierto_en] DEFAULT (SYSDATETIME()),
    [cerrado_en] DATETIME2(0) NULL,
    [monto_apertura] DECIMAL(12,2) NULL CONSTRAINT [df_sesiones_caja_monto_apertura] DEFAULT (0.00),
    [monto_cierre] DECIMAL(12,2) NULL,
    [monto_esperado] DECIMAL(12,2) NULL,
    [diferencia] DECIMAL(12,2) NULL,
    [estado] NVARCHAR(20) NULL CONSTRAINT [df_sesiones_caja_estado] DEFAULT (N'abierto'),
    CONSTRAINT [pk_sesiones_caja] PRIMARY KEY ([id])
);
CREATE TABLE dbo.[unidades] (
    [id] INT IDENTITY(1,1) NOT NULL,
    [nombre] NVARCHAR(50) NOT NULL,
    [simbolo] NVARCHAR(10) NULL,
    CONSTRAINT [pk_unidades] PRIMARY KEY ([id])
);
CREATE TABLE dbo.[usuarios] (
    [id_usuario] INT IDENTITY(1,1) NOT NULL,
    [usuario] NVARCHAR(100) NOT NULL,
    [email] NVARCHAR(150) NULL,
    [password_hash] NVARCHAR(255) NULL,
    [rol_id] INT NULL,
    [activo] BIT NULL CONSTRAINT [df_usuarios_activo] DEFAULT (1),
    [creado_en] DATETIME2(0) NOT NULL CONSTRAINT [df_usuarios_creado_en] DEFAULT (SYSDATETIME()),
    [actualizado_en] DATETIME2(0) NULL,
    CONSTRAINT [pk_usuarios] PRIMARY KEY ([id_usuario])
);
CREATE TABLE dbo.[variantes_producto] (
    [id] INT IDENTITY(1,1) NOT NULL,
    [producto_id] INT NOT NULL,
    [marca_id] INT NULL,
    [sku] NVARCHAR(100) NULL,
    [codigo_barras] NVARCHAR(100) NULL,
    [nombre] NVARCHAR(255) NULL,
    [costo_extra] DECIMAL(12,2) NULL CONSTRAINT [df_variantes_producto_costo_extra] DEFAULT (0.00),
    [precio_venta] DECIMAL(12,2) NULL CONSTRAINT [df_variantes_producto_precio_venta] DEFAULT (0.00),
    [stock] DECIMAL(12,3) NULL CONSTRAINT [df_variantes_producto_stock] DEFAULT (0.000),
    [stock_minimo] DECIMAL(12,3) NULL CONSTRAINT [df_variantes_producto_stock_minimo] DEFAULT (0.000),
    [activo] BIT NULL CONSTRAINT [df_variantes_producto_activo] DEFAULT (1),
    [creado_en] DATETIME2(0) NOT NULL CONSTRAINT [df_variantes_producto_creado_en] DEFAULT (SYSDATETIME()),
    [fecha_vencimiento] DATE NULL,
    CONSTRAINT [pk_variantes_producto] PRIMARY KEY ([id])
);
CREATE TABLE dbo.[ventas] (
    [id] INT IDENTITY(1,1) NOT NULL,
    [cliente_id] INT NULL,
    [sesion_caja_id] INT NULL,
    [fecha] DATETIME2(0) NULL CONSTRAINT [df_ventas_fecha] DEFAULT (SYSDATETIME()),
    [total] DECIMAL(12,2) NULL CONSTRAINT [df_ventas_total] DEFAULT (0.00),
    [metodo_pago_id] INT NULL,
    [metodo_pago] NVARCHAR(50) NULL,
    [observaciones] NVARCHAR(MAX) NULL,
    [estado] NVARCHAR(9) NULL CONSTRAINT [df_ventas_estado] DEFAULT (N'pagada'),
    [tipo_comprobante] NVARCHAR(20) NOT NULL CONSTRAINT [df_ventas_tipo_comprobante] DEFAULT (N'boleta'),
    [numero_comprobante] NVARCHAR(50) NULL,
    [creado_por] INT NULL,
    CONSTRAINT [pk_ventas] PRIMARY KEY ([id]),
    CONSTRAINT [ck_ventas_estado] CHECK ([estado] IN (N'pendiente', N'pagada', N'anulada'))
);
