-- ===================================================== PROCEDIMIENTOS
-- Equivalencias usadas:  DAYOFWEEK(d) (1=domingo) -> (DATEDIFF(DAY,'19000107',d) % 7) + 1
--   ELT -> CHOOSE · IF() -> IIF · LAST_INSERT_ID() -> SCOPE_IDENTITY() · LIMIT 1 -> TOP 1
--   LPAD -> RIGHT(REPLICATE('0',n)+x, n) · TIMESTAMP(d,h) -> DATEADD(SECOND, ..., d)

CREATE PROCEDURE dbo.sp_seed_compras
    @p_desde DATE,
    @p_hasta DATE
AS
BEGIN
  SET NOCOUNT ON;
  DECLARE @v_dia    DATE;
  DECLARE @v_compra INT;
  DECLARE @v_prov   INT;
  DECLARE @v_total  DECIMAL(12,2);
  DECLARE @v_var    INT;
  DECLARE @v_cant   DECIMAL(12,3);
  DECLARE @v_costo  DECIMAL(12,2);
  DECLARE @v_k      INT;
  DECLARE @v_stock  DECIMAL(12,3);

  SET @v_dia = @p_desde;
  WHILE @v_dia <= @p_hasta
  BEGIN
    IF (DATEDIFF(DAY, '19000107', @v_dia) % 7) + 1 = 2          -- lunes: día de compra
    BEGIN
      SET @v_prov = CHOOSE(CAST(FLOOR(RAND()*3) AS INT) + 1, 1, 3, 7);
                           estado, observaciones, creado_por)
      VALUES (@v_prov,
              CONCAT('F001-', RIGHT(REPLICATE('0', 6) + CAST(CAST(FLOOR(RAND()*899999) + 100000 AS INT) AS VARCHAR(20)), 6)),
              DATEADD(MINUTE, 8*60 + 30, CAST(@v_dia AS DATETIME2(0))), 0, N'recibida',
              N'SEED-T2 compra semanal de insumos', 1);
      SET @v_compra = SCOPE_IDENTITY();
      SET @v_total  = 0;
      SET @v_k      = 1;

      WHILE @v_k <= 4
      BEGIN
        /* insumo, cantidad y costo unitario por variante */
        SET @v_var = CHOOSE(@v_k, 22, 23, 24, 2);
        SET @v_cant = CASE @v_k
                       WHEN 1 THEN 8 + FLOOR(RAND()*5)      -- harina integral (sacos 25 kg)
                       WHEN 2 THEN 3 + FLOOR(RAND()*3)      -- azucar (sacos 25 kg)
                       WHEN 3 THEN 4 + FLOOR(RAND()*3)      -- mantequilla (cajas 10 kg)
                       ELSE        2 + FLOOR(RAND()*2) END; -- levadura (bolsas 500 g)
        SET @v_costo = CASE @v_k
                       WHEN 1 THEN 95.00 + ROUND(RAND()*6, 2)
                       WHEN 2 THEN 88.00 + ROUND(RAND()*5, 2)
                       WHEN 3 THEN 145.00 + ROUND(RAND()*9, 2)
                       ELSE        9.00 + ROUND(RAND()*1, 2) END;

                                  margen_porcentaje, precio_venta_resultante, total)
        VALUES (@v_compra, @v_var, @v_cant, @v_costo, 30.00,
                ROUND(@v_costo*1.30, 2), ROUND(@v_cant*@v_costo, 2));

        SET @v_total = @v_total + ROUND(@v_cant*@v_costo, 2);

        SET @v_stock = (SELECT stock FROM variantes_producto WHERE id = @v_var);
           referencia_id, fecha, usuario_id)
        VALUES (@v_var, N'Entrada por Compra',
                CONCAT(N'SEED-T2 compra #', @v_compra),
                @v_cant, @v_stock, @v_stock + @v_cant, @v_compra,
                DATEADD(MINUTE, 8*60 + 30, CAST(@v_dia AS DATETIME2(0))), 1);
        UPDATE variantes_producto SET stock = stock + @v_cant WHERE id = @v_var;

        SET @v_k = @v_k + 1;
      END;

      /* una compra de reventa cada dos semanas */
      IF RAND() < 0.5
      BEGIN
        SET @v_cant  = 24 + FLOOR(RAND()*24);
        SET @v_costo = 2.30 + ROUND(RAND()*0.4, 2);
                                  margen_porcentaje, precio_venta_resultante, total)
        VALUES (@v_compra, 4, @v_cant, @v_costo, 52.00, 3.50, ROUND(@v_cant*@v_costo, 2));
        SET @v_total = @v_total + ROUND(@v_cant*@v_costo, 2);
        SET @v_stock = (SELECT stock FROM variantes_producto WHERE id = 4);
           referencia_id, fecha, usuario_id)
        VALUES (4, N'Entrada por Compra', CONCAT(N'SEED-T2 compra #', @v_compra),
                @v_cant, @v_stock, @v_stock + @v_cant, @v_compra,
                DATEADD(MINUTE, 8*60 + 35, CAST(@v_dia AS DATETIME2(0))), 1);
        UPDATE variantes_producto SET stock = stock + @v_cant WHERE id = 4;
      END;

      UPDATE compras SET total = @v_total WHERE id = @v_compra;
    END;
    SET @v_dia = DATEADD(DAY, 1, @v_dia);
  END;
END;
GO

CREATE PROCEDURE dbo.sp_seed_produccion
    @p_desde DATE,
    @p_hasta DATE
AS
BEGIN
  SET NOCOUNT ON;
  DECLARE @v_dia     DATE;
  DECLARE @v_t       INT;
  DECLARE @v_receta  INT;
  DECLARE @v_varsal  INT;
  DECLARE @v_prod    INT;
  DECLARE @v_prodid  INT;
  DECLARE @v_prog    DECIMAL(12,3);
  DECLARE @v_merma   DECIMAL(12,3);
  DECLARE @v_obt     DECIMAL(12,3);
  DECLARE @v_pctmer  DECIMAL(6,4);
  DECLARE @v_motivo  NVARCHAR(255);
  DECLARE @v_hora    TIME(0);
  DECLARE @v_fecha   DATETIME2(0);
  DECLARE @v_factor  DECIMAL(6,3);
  DECLARE @v_stock   DECIMAL(12,3);
  DECLARE @v_lotes   DECIMAL(12,3);
  DECLARE @v_dow     INT;

  SET @v_dia = @p_desde;
  WHILE @v_dia <= @p_hasta
  BEGIN
    SET @v_dow = (DATEDIFF(DAY, '19000107', @v_dia) % 7) + 1;   -- 1=domingo ... 7=sábado

    /* fin de semana: +25 % de demanda; lunes: -10 % */
    SET @v_factor = CASE
        WHEN @v_dow IN (1,7) THEN 1.25
        WHEN @v_dow = 2      THEN 0.90
        ELSE 1.00 END;

    SET @v_t = 1;
    WHILE @v_t <= 5
    BEGIN
      /* 1 y 2: pan francés mañana y tarde · 3: croissant
         4: pan de molde · 5: torta (solo algunos días) */
      SET @v_receta = CASE @v_t
          WHEN 1 THEN 4 WHEN 2 THEN 4
          WHEN 3 THEN (SELECT TOP 1 id FROM recetas WHERE producto_id = 22)
          WHEN 4 THEN (SELECT TOP 1 id FROM recetas WHERE producto_id = 21)
          ELSE        (SELECT TOP 1 id FROM recetas WHERE producto_id = 23) END;
      SET @v_varsal = CASE @v_t
          WHEN 1 THEN 15 WHEN 2 THEN 15 WHEN 3 THEN 26
          WHEN 4 THEN 25 ELSE 27 END;
      SET @v_prod = CASE @v_t
          WHEN 1 THEN 9 WHEN 2 THEN 9 WHEN 3 THEN 22
          WHEN 4 THEN 21 ELSE 23 END;
      SET @v_hora = CASE @v_t
          WHEN 1 THEN '04:30:00' WHEN 2 THEN '15:00:00'
          WHEN 3 THEN '05:15:00' WHEN 4 THEN '05:45:00'
          ELSE '09:00:00' END;
      SET @v_fecha = DATEADD(SECOND, DATEDIFF(SECOND, CAST('00:00:00' AS TIME(0)), @v_hora),
                             CAST(@v_dia AS DATETIME2(0)));

      SET @v_prog = CASE @v_t
          WHEN 1 THEN ROUND((820 + FLOOR(RAND()*140)) * @v_factor, 0)
          WHEN 2 THEN ROUND((680 + FLOOR(RAND()*130)) * @v_factor, 0)
          WHEN 3 THEN ROUND((110 + FLOOR(RAND()*45))  * @v_factor, 0)
          WHEN 4 THEN ROUND((55  + FLOOR(RAND()*30))  * @v_factor, 0)
          ELSE        FLOOR(RAND()*4) + 1 END;

      IF @v_t < 5 OR RAND() < 0.45
      BEGIN
        /* merma entre 9 % y 16 %, media ≈ 13 % */
        SET @v_pctmer = 0.09 + RAND()*0.07;
        SET @v_merma  = ROUND(@v_prog * @v_pctmer, 0);
        IF @v_merma < 1 SET @v_merma = 1;                 -- GREATEST(..., 1)
        SET @v_obt    = @v_prog - @v_merma;

        SET @v_motivo = CASE
            WHEN RAND() < 0.45 THEN N'Panes quemados en horno'
            WHEN RAND() < 0.60 THEN N'Piezas con deformacion en horneado'
            WHEN RAND() < 0.80 THEN N'Perdida normal de proceso'
            ELSE                    N'Caida durante manipulacion' END;

           cantidad_obtenida, merma_cantidad, merma_motivo, fecha,
           producido_por, estado, observaciones)
        VALUES (CONCAT('OP-', CONVERT(CHAR(8), @v_dia, 112), '-', @v_t),
                @v_receta, @v_varsal, @v_prog, @v_obt, @v_merma, @v_motivo,
                @v_fecha, 3, N'finalizada', N'SEED-T2 orden de produccion');
        SET @v_prodid = SCOPE_IDENTITY();

        VALUES (@v_prodid, @v_prod, @v_obt);

        /* lotes equivalentes = obtenido / rendimiento de la receta */
        SET @v_lotes = @v_obt / (SELECT rendimiento FROM recetas WHERE id = @v_receta);

        /* consumo de insumos según receta */
        SELECT @v_prodid, dr.variante_id, ROUND(dr.cantidad * @v_lotes, 3), @v_fecha
        FROM detalle_receta dr WHERE dr.receta_id = @v_receta;

        /* salida de insumos del inventario */
           referencia_id, fecha, usuario_id)
        SELECT dr.variante_id, N'Salida por Producción',
               CONCAT(N'SEED-T2 consumo OP #', @v_prodid),
               ROUND(dr.cantidad * @v_lotes, 3),
               vp.stock, vp.stock - ROUND(dr.cantidad * @v_lotes, 3),
               @v_prodid, @v_fecha, 3
        FROM detalle_receta dr
        JOIN variantes_producto vp ON vp.id = dr.variante_id
        WHERE dr.receta_id = @v_receta;

        UPDATE vp
        SET vp.stock = vp.stock - x.c
        FROM variantes_producto vp
        JOIN (SELECT dr.variante_id AS vid,
                     SUM(ROUND(dr.cantidad * @v_lotes, 3)) AS c
              FROM detalle_receta dr
              WHERE dr.receta_id = @v_receta
              GROUP BY dr.variante_id) x ON x.vid = vp.id;

        /* entrada de producto terminado */
        SET @v_stock = (SELECT stock FROM variantes_producto WHERE id = @v_varsal);
           referencia_id, fecha, usuario_id)
        VALUES (@v_varsal, N'Entrada por Producción',
                CONCAT(N'SEED-T2 ingreso OP #', @v_prodid),
                @v_obt, @v_stock, @v_stock + @v_obt, @v_prodid,
                DATEADD(MINUTE, 90, @v_fecha), 3);
        UPDATE variantes_producto SET stock = stock + @v_obt WHERE id = @v_varsal;
      END;
      SET @v_t = @v_t + 1;
    END;

    SET @v_dia = DATEADD(DAY, 1, @v_dia);
  END;
END;
GO

CREATE PROCEDURE dbo.sp_seed_ventas
    @p_desde DATE,
    @p_hasta DATE
AS
BEGIN
  SET NOCOUNT ON;
  DECLARE @v_dia     DATE;
  DECLARE @v_factor  DECIMAL(6,3);
  DECLARE @v_ses_m   INT;
  DECLARE @v_ses_t   INT;
  DECLARE @v_n       INT;
  DECLARE @v_i       INT;
  DECLARE @v_r       DECIMAL(10,6);
  DECLARE @v_hora    INT;
  DECLARE @v_min     INT;
  DECLARE @v_fecha   DATETIME2(0);
  DECLARE @v_venta   INT;
  DECLARE @v_cli     INT;
  DECLARE @v_mp      INT;
  DECLARE @v_caj     INT;
  DECLARE @v_ses     INT;
  DECLARE @v_lin     INT;
  DECLARE @v_j       INT;
  DECLARE @v_var     INT;
  DECLARE @v_cant    DECIMAL(12,3);
  DECLARE @v_precio  DECIMAL(12,2);
  DECLARE @v_desc    DECIMAL(12,2);
  DECLARE @v_total   DECIMAL(12,2);
  DECLARE @v_stock   DECIMAL(12,3);
  DECLARE @v_tipo    NVARCHAR(20);
  DECLARE @v_corr    INT = 0;
  DECLARE @v_dow     INT;

  SET @v_dia = @p_desde;
  WHILE @v_dia <= @p_hasta
  BEGIN
    SET @v_dow = (DATEDIFF(DAY, '19000107', @v_dia) % 7) + 1;   -- 1=domingo ... 7=sábado
    SET @v_factor = CASE
        WHEN @v_dow IN (1,7) THEN 1.25
        WHEN @v_dow = 2      THEN 0.90
        ELSE 1.00 END;

    /* sesiones de caja del día */
                               monto_cierre, monto_esperado, diferencia, estado)
    VALUES (2, DATEADD(HOUR, 6, CAST(@v_dia AS DATETIME2(0))), DATEADD(HOUR, 14, CAST(@v_dia AS DATETIME2(0))),
            100.00, NULL, NULL, NULL, N'cerrado');
    SET @v_ses_m = SCOPE_IDENTITY();

                               monto_cierre, monto_esperado, diferencia, estado)
    VALUES (2, DATEADD(HOUR, 14, CAST(@v_dia AS DATETIME2(0))), DATEADD(HOUR, 21, CAST(@v_dia AS DATETIME2(0))),
            100.00, NULL, NULL, NULL, N'cerrado');
    SET @v_ses_t = SCOPE_IDENTITY();

    SET @v_n = ROUND((34 + FLOOR(RAND()*16)) * @v_factor, 0);
    SET @v_i = 1;

    WHILE @v_i <= @v_n
    BEGIN
      /* ---- hora según distribución de demanda ---- */
      SET @v_r = RAND();
      SET @v_hora = CASE
          WHEN @v_r < 0.38 THEN 6  + FLOOR(RAND()*3)   -- 06-08  desayuno
          WHEN @v_r < 0.53 THEN 9  + FLOOR(RAND()*3)   -- 09-11
          WHEN @v_r < 0.65 THEN 12 + FLOOR(RAND()*5)   -- 12-16
          WHEN @v_r < 0.95 THEN 17 + FLOOR(RAND()*4)   -- 17-20  lonche
          ELSE                  21 END;
      SET @v_min   = FLOOR(RAND()*60);
      SET @v_fecha = DATEADD(SECOND, @v_hora*3600 + @v_min*60 + CAST(FLOOR(RAND()*60) AS INT),
                             CAST(@v_dia AS DATETIME2(0)));
      SET @v_ses   = IIF(@v_hora < 14, @v_ses_m, @v_ses_t);
      SET @v_caj   = 2;

      /* ---- cliente: 78 % consumidor final sin identificar ---- */
      SET @v_cli = IIF(RAND() < 0.78, NULL,
                       CHOOSE(CAST(FLOOR(RAND()*5) AS INT) + 1, 2, 7, 8, 9, 10));

      /* ---- medio de pago ---- */
      SET @v_r  = RAND();
      SET @v_mp = CASE
          WHEN @v_r < 0.46 THEN 1   -- Efectivo
          WHEN @v_r < 0.72 THEN 3   -- Yape
          WHEN @v_r < 0.84 THEN 4   -- Plin
          WHEN @v_r < 0.95 THEN 2   -- Tarjeta
          ELSE                  5 END;

      SET @v_tipo = IIF(@v_cli IS NOT NULL AND RAND() < 0.5, N'factura', N'boleta');
      SET @v_corr = @v_corr + 1;

                          metodo_pago, observaciones, estado, tipo_comprobante,
                          numero_comprobante, creado_por)
      VALUES (@v_cli, @v_ses, @v_fecha, 0, @v_mp, NULL, N'SEED-T2 venta simulada',
              IIF(RAND() < 0.02, N'anulada', N'pagada'),
              @v_tipo,
              CONCAT(IIF(@v_tipo = N'factura', 'F001-', 'B001-'),
                     RIGHT(REPLICATE('0', 7) + CAST(@v_corr + DATEPART(DAYOFYEAR, @v_dia)*100 AS VARCHAR(20)), 7)),
              @v_caj);
      SET @v_venta = SCOPE_IDENTITY();

      SET @v_total = 0;
      SET @v_lin   = 1 + FLOOR(RAND()*3);
      SET @v_j     = 1;

      WHILE @v_j <= @v_lin
      BEGIN
        /* ---- producto según participación de la línea ---- */
        SET @v_r = RAND();
        SET @v_var = CASE
            WHEN @v_r < 0.58 THEN 15   -- Pan francés
            WHEN @v_r < 0.76 THEN 26   -- Croissant
            WHEN @v_r < 0.88 THEN 25   -- Pan de molde
            WHEN @v_r < 0.93 THEN 4    -- Gaseosa (reventa)
            WHEN @v_r < 0.97 THEN 11   -- Yogurt griego (reventa)
            ELSE                  27 END; -- Torta

        SET @v_cant = CASE @v_var
            WHEN 15 THEN 3 + FLOOR(RAND()*16)
            WHEN 26 THEN 1 + FLOOR(RAND()*4)
            WHEN 25 THEN 1 + FLOOR(RAND()*3)
            WHEN 27 THEN 1
            ELSE         1 + FLOOR(RAND()*2) END;

        SET @v_precio = (SELECT precio_venta FROM variantes_producto WHERE id = @v_var);
        SET @v_desc   = IIF(RAND() < 0.12, ROUND(@v_cant*@v_precio*0.05, 2), 0.00);

                                 precio_unitario, descuento)
        VALUES (@v_venta, @v_var, @v_cant, @v_precio, @v_desc);

        SET @v_total = @v_total + ROUND(@v_cant*@v_precio - @v_desc, 2);

        /* salida de producto terminado */
        SET @v_stock = (SELECT stock FROM variantes_producto WHERE id = @v_var);
           referencia_id, fecha, usuario_id)
        VALUES (@v_var, N'Salida por Venta',
                CONCAT(N'SEED-T2 venta #', @v_venta),
                @v_cant, @v_stock, @v_stock - @v_cant, @v_venta, @v_fecha, @v_caj);
        UPDATE variantes_producto SET stock = stock - @v_cant WHERE id = @v_var;

        SET @v_j = @v_j + 1;
      END;

      UPDATE ventas SET total = @v_total WHERE id = @v_venta;
      SET @v_i = @v_i + 1;
    END;

    /* cierre de caja coherente con lo vendido en efectivo */
    UPDATE s
    SET s.monto_esperado = s.monto_apertura + COALESCE((
            SELECT SUM(v.total) FROM ventas v
            WHERE v.sesion_caja_id = s.id AND v.metodo_pago_id = 1
              AND v.estado = N'pagada'), 0),
        s.monto_cierre   = s.monto_apertura + COALESCE((
            SELECT SUM(v.total) FROM ventas v
            WHERE v.sesion_caja_id = s.id AND v.metodo_pago_id = 1
              AND v.estado = N'pagada'), 0) - ROUND(RAND()*4, 2),
        s.diferencia     = -ROUND(RAND()*4, 2)
    FROM sesiones_caja s
    WHERE s.id IN (@v_ses_m, @v_ses_t);

    SET @v_dia = DATEADD(DAY, 1, @v_dia);
  END;
END;
GO
